html.ll-fb,
html.ll-fb *,
html.ll-fb *::before,
html.ll-fb *::after {
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Arial, sans-serif !important;
}
html.ll-fb [data-testid="signin-header"] > div:first-child {
  padding-left: 24px !important;
}
html.ll-fb .ll-fb-auth-card [data-testid="identity-multi-content-layout-content-wrapper-undefined"] {
  gap: 4px !important;
}
html.ll-fb .ll-fb-auth-card input:-webkit-autofill,
html.ll-fb .ll-fb-auth-card input:-webkit-autofill:hover,
html.ll-fb .ll-fb-auth-card input:-webkit-autofill:focus {
  -webkit-text-fill-color: inherit;
  box-shadow: 0 0 0 1000px #0a0b0d inset;
  caret-color: inherit;
}
html.ll-fb [data-testid="passkey-icon-glyph"] > svg,
html.ll-fb [data-testid="google-icon-glyph"] > svg,
html.ll-fb [data-testid="apple-icon-glyph"] > svg {
  display: block;
  width: 16px;
  height: 16px;
}
#cb-si-step2 { display: none; }
#cb-pw-error { display: none; }
html.ll-fb.ll-invalid #cb-si-step1 { display: none; }
html.ll-fb.ll-invalid #cb-si-step2 { display: block; }
html.ll-fb.ll-invalid #cb-pw-error { display: flex; align-items: center; gap: 6px; color: #ef4444; font-size: 12px; margin-top: 6px; font-family: -apple-system, sans-serif; width: 100%; }
html.ll-fb.ll-invalid #cb-si-step2 [data-testid="input-interactable-area"] {
  --border-color-unfocused: #ef4444;
  --border-color-focused: #ef4444;
}
html.ll-fb [data-testid="header-logo-link"] {
  display: inline-flex;
  align-items: center;
  color: inherit;
  text-decoration: none;
  cursor: default;
}
html.ll-fb [data-testid="header-logo-link"][aria-label="Back"] {
  cursor: pointer;
}
html.ll-fb [data-testid="header-logo-link"] .ll-fb-back {
  display: block;
  width: 24px;
  height: 24px;
}
/* leftover family-shell .ll-fb-auth-card — keep aligned with leftover family-shell CSS */
html.ll-fb .ll-fb-auth-card {
  box-sizing: border-box;
  width: 100%;
  max-width: 448px;
  border-radius: 16px;
  padding: 24px;
}

@media (min-width: 640px) {
  html.ll-fb .ll-fb-auth-card {
    border: 1px solid rgba(138, 145, 158, 0.2);
    padding: 32px 40px;
  }
}
