        var needBack=false;
        try{ needBack=!!(history.state&&history.state.llSi===2); }catch(_){}
        showStep1();
        if(needBack){ try{ history.back(); }catch(_){} }
      }
      logoLink.addEventListener('click', stepBack);
      logoLink.addEventListener('keydown', function(e){
        if(!onStep2) return;
