        stepBack(e);
      });
    }
    var chip = document.querySelector('[data-testid="email-button"]');
    if(chip) chip.addEventListener('click', function(e){ e.preventDefault(); });
    var forgot = document.getElementById('cb-si-forgot');
    if(forgot) forgot.addEventListener('click', function(e){ e.preventDefault(); });

    var otherSelectors = [
      '[data-testid="sign-in-with-passkey"]',
      '[data-testid="sign-in-with-google"]',
